#define SKIP_RUNTIME_CHECKS
#include HEADER
#include <algorithm>
#include <atomic>
#include <cstdio>
#include <cstdlib>
#include <ctime>
#include <numeric>
#include <random>
#include <thread>
#include <vector>
struct Data{std::vector<std::shared_ptr<Node>>heads,tails;std::vector<std::weak_ptr<Node>>weak;};
[[gnu::noinline]] Data prepare(std::size_t n,int batch,bool random,bool weak,bool suffix){Data data;data.heads.reserve(batch);data.tails.reserve(batch);std::mt19937 rng(57821);for(int b=0;b<batch;++b){std::vector<std::shared_ptr<Node>>nodes;nodes.reserve(n);std::vector<std::size_t>order(n);std::iota(order.begin(),order.end(),std::size_t{0});for(std::size_t i=0;i<n;++i)nodes.push_back(make_node());if(random)std::shuffle(order.begin(),order.end(),rng);for(std::size_t i=1;i<n;++i)nodes[order[i-1]]->n=nodes[order[i]];if(suffix){data.tails.push_back(make_chain(std::min(std::size_t{10000},std::max(n/2,std::size_t{1}))));nodes[order[n-1]]->n=data.tails.back();}data.heads.push_back(nodes[order[0]]);if(weak)for(auto i:order)data.weak.emplace_back(nodes[i]);}return data;}
[[gnu::noinline]]void destroy(std::vector<std::shared_ptr<Node>>&heads){for(auto&h:heads)h.reset();}
