#ifndef SIRKIT_NODE_DEFINED
#define SIRKIT_NODE_DEFINED
struct Node {
    std::shared_ptr<Node> n;

    explicit Node(std::shared_ptr<Node> next = {}) noexcept : n(std::move(next)) {}
    Node(const Node&) noexcept = default;
    Node(Node&&) noexcept = default;
    Node& operator=(const Node&) noexcept = default;
    Node& operator=(Node&&) noexcept = default;

    ~Node() {
        if (!n || !n->n) return;
        if (n.use_count() != 1) return;
        destroy_suffix(n);
    }
private:
#if defined(__GNUC__) || defined(__clang__)
    [[gnu::noinline]]
#endif
    static void destroy_suffix(std::shared_ptr<Node>& link) noexcept {
        auto current = std::move(link);
        do {
            current = std::move(current->n);
        } while (current.use_count() == 1 && current);
    }

};
#endif

