};
}  // namespace reinsirk::detail
#endif
#endif

#ifndef SIRKIT_CHAIN_SIZE_DEFINED
#define SIRKIT_CHAIN_SIZE_DEFINED
inline std::size_t chain_size(const std::shared_ptr<Node>& head) {
    std::size_t size = 0;
