#include HEADER
#include <algorithm>
#include <chrono>
#include <ctime>
#include <iostream>
#include <random>
#include <vector>
#include <atomic>
[[gnu::noinline]] std::size_t run(const std::shared_ptr<Node>& p, std::size_t index, int kind) {
 if(kind==0)return reinterpret_cast<std::uintptr_t>(chain_nth(p,index).get());
 return reinterpret_cast<std::uintptr_t>(chain_tail(p).get());
}
int main(int argc,char**argv){
 std::size_t n=std::stoull(argv[1]),reps=std::stoull(argv[2]);int layout=std::stoi(argv[3]),kind=std::stoi(argv[4]);
 std::vector<std::shared_ptr<Node>>nodes(n);for(auto&x:nodes)x=make_node();
 std::vector<std::size_t>order(n);for(std::size_t i=0;i<n;++i)order[i]=i;
 if(layout){std::mt19937_64 rng(1919);std::shuffle(order.begin(),order.end(),rng);}
 for(std::size_t i=1;i<n;++i)nodes[order[i-1]]->n=nodes[order[i]];
 std::shared_ptr<Node>head=n?nodes[order[0]]:nullptr;auto want=n?nodes[order.back()].get():nullptr;
 std::size_t sum=0;std::atomic_signal_fence(std::memory_order_seq_cst);auto t=std::clock();
 for(std::size_t i=0;i<reps;++i)sum^=run(head,n?n-1:0,kind)+i;
 std::atomic_signal_fence(std::memory_order_seq_cst);double ms=1000.0*(std::clock()-t)/CLOCKS_PER_SEC;
 if(run(head,n?n-1:0,kind)!=reinterpret_cast<std::uintptr_t>(want))return 2;
 std::cout<<ms<<' '<<reps<<'\n';for(auto&x:nodes)x->n.reset();
 std::cerr<<sum<<'\n';
}

