for n in [0,1,2,8,32,1024,100000,1000000]:
 for layout in ([0,1] if n>=32 else[0]):
  for kind in [0,1]:cases.append((n,max(1,1000000//max(n,1)),layout,kind))
for compiler,cfg,check in [('gcc','default','skip'),('gcc','native','skip'),('clang','default','skip'),('gcc','default','check'),('clang','default','check')]:
 for v in variants:
  cmd=['taskset','-c','4','/usr/bin/g++'if compiler=='gcc'else'clang++','-std=c++23','-O2',f'-DHEADER="{p/(v+".hpp")}"',str(p/'walk_bench.cpp'),'-o',str(p/'walk-current')]
