  q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr;data=(p/'walk-current').read_bytes();(p/f'walk-{v}').write_bytes(data);builds.append(dict(compiler=compiler,cfg=cfg,check=check,variant=v,cmd=cmd,binary_sha=hashlib.sha256(data).hexdigest()))
 for case in cases:
  for rep in range(7):
   order=variants+['control'];random.Random(912+rep).shuffle(order)
   for v in order:
    dest=p/'walk-run';dest.write_bytes((p/f'walk-{v if v!="control"else"base"}').read_bytes());dest.chmod(0o755);cmd=['taskset','-c','4',str(dest),*map(str,case)];q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0,(cmd,q.stderr);t,reps=q.stdout.split();rows.append(dict(compiler=compiler,cfg=cfg,check=check,case=case,variant=v,rep=rep,ms=float(t)))
  (p/'walk-raw.json').write_text(json.dumps(dict(builds=builds,rows=rows),indent=2)+'\n')
 print(compiler,cfg,check,'done',flush=True)
s=[]
for build in builds[::len(variants)]:
 compiler,cfg,check=[build[k]for k in ['compiler','cfg','check']]
 for case in cases:
  z=[x for x in rows if x['compiler']==compiler and x['cfg']==cfg and x['check']==check and tuple(x['case'])==case];d={v:statistics.median(x['ms']for x in z if x['variant']==v)for v in variants+['control']};s.append(dict(compiler=compiler,cfg=cfg,check=check,case=case,ms=d,ratio={v:d[v]/d['base']for v in d}))
(p/'walk-summary.json').write_text(json.dumps(s,indent=2)+'\n')
